354	  ctx.beginPath();
355	  ctx.arc(cx, cy, r, startAngle, fillEnd);
356	  ctx.strokeStyle = `hsl(${hue},90%,50%)`;
357	  ctx.lineWidth = 10;
358	  ctx.stroke();
359	
360	  // needle
361	  const needleAngle = startAngle + normalizedSpeed * Math.PI;
362	  ctx.beginPath();
363	  ctx.moveTo(cx, cy);
364	  ctx.lineTo(cx + Math.cos(needleAngle) * (r - 4), cy + Math.sin(needleAngle) * (r - 4));
365	  ctx.strokeStyle = 'white';
366	  ctx.lineWidth = 2.5;
367	  ctx.stroke();
368	
369	  // label
370	  ctx.fillStyle = 'rgba(255,255,255,0.7)';
