380	
381	  ctx.beginPath();
382	  ctx.arc(0, 0, 10, 0, Math.PI * 2);
383	  ctx.fillStyle = state === 'SWINGING' ? '#f9c74f' : 'rgba(255,255,255,0.5)';
384	  ctx.fill();
385	  ctx.strokeStyle = '#333';
386	  ctx.lineWidth = 2.5;
387	  ctx.stroke();
388	
389	  // little grip lines
390	  for (let i = 0; i < 3; i++) {
391	    const y = -3 + i * 3;
392	    ctx.beginPath();
393	    ctx.moveTo(-5, y);
394	    ctx.lineTo(5, y);
395	    ctx.strokeStyle = 'rgba(0,0,0,0.4)';
396	    ctx.lineWidth = 1.5;
397	    ctx.stroke();
398	  }
399	
400	  ctx.restore();
401	}
402	
403	function drawHpBar(fraction) {
404	  const barW = 160;
405	  const barH = 12;
406	  const x = canvasW - barW - 20;
407	  const y = canvasH - 68;
408	
409	  ctx.fillStyle = 'rgba(0,0,0,0.4)';
410	  ctx.fillRect(x, y, barW, barH);
411	
412	  const hue = fraction * 120; // green → red as HP drops
413	  ctx.fillStyle = `hsl(${hue},85%,50%)`;
414	  ctx.fillRect(x, y, barW * Math.max(0, fraction), barH);
415	
416	  ctx.strokeStyle = 'rgba(255,255,255,0.25)';
417	  ctx.lineWidth = 1;
418	  ctx.strokeRect(x, y, barW, barH);
419	
420	  ctx.fillStyle = 'rgba(255,255,255,0.65)';
421	  ctx.font = 'bold 10px system-ui';
422	  ctx.textAlign = 'right';
423	  ctx.fillText('HP', x - 6, y + barH - 1);
424	  ctx.textAlign = 'left';
425	}
426	
427	function drawHitCounter(hitCount) {
428	  ctx.fillStyle = 'rgba(255,255,255,0.65)';
429	  ctx.font = 'bold 12px system-ui';
430	  ctx.textAlign = 'right';
431	  ctx.fillText(`Hits: ${hitCount}`, canvasW - 20, canvasH - 82);
432	  ctx.textAlign = 'left';
433	}
