export const LEVELS = [
  {
    id: 1,
    name: 'Greenhouse',
    background: ['#4a7c59', '#2d5a3d'],
    groundColor: '#5c4a2a',
    yoyoType: 'standard',
    stringLength: 130,
    pushStringLength: 140,
    pivot: { x: 0.24, y: 0.48 },
    targets: [
      { shape: 'rectangle', w: 58, h: 82, x: 0.72, y: 0.58, material: 'glass' },
      { shape: 'rectangle', w: 52, h: 62, x: 0.60, y: 0.62, material: 'wood' },
    ],
    parScore: 1200,
    pushParScore: 1500,
    hint: 'Move your mouse in circles to build speed, then release!',
  },
  {
    id: 2,
    name: 'Scrapyard',
    background: ['#6b4c3b', '#3d2b1f'],
    groundColor: '#2c2c2c',
    yoyoType: 'heavy',
    stringLength: 140,
    pushStringLength: 100,
    pivot: { x: 0.21, y: 0.50 },
    targets: [
      { shape: 'rectangle', w: 70, h: 50, x: 0.68, y: 0.62, material: 'steel' },
      { shape: 'rectangle', w: 48, h: 70, x: 0.80, y: 0.58, material: 'wood' },
      { shape: 'rectangle', w: 44, h: 44, x: 0.56, y: 0.65, material: 'glass' },
    ],
    parScore: 2800,
    pushParScore: 2000,
    hint: 'The iron yoyo is slow but hits like a truck. Full speed for steel!',
  },
];

const SAVE_KEY = 'yoyo_progress';

export function loadProgress() {
  try {
    return JSON.parse(localStorage.getItem(SAVE_KEY) || '{}');
  } catch {
    return {};
  }
}

export function saveProgress(levelId, score) {
  const data = loadProgress();
  if (!data.highScores) data.highScores = {};
  if (score > (data.highScores[levelId] || 0)) data.highScores[levelId] = score;
  data.unlockedLevel = Math.max(data.unlockedLevel || 1, levelId + 1);
  try { localStorage.setItem(SAVE_KEY, JSON.stringify(data)); } catch {}
}

export function getLevel(id) {
  return LEVELS.find(l => l.id === id) || LEVELS[0];
}

export const MATERIALS = {
  glass: {
    strength: 220,
    crackThreshold: 85,
    fragmentCount: 10,
    fragmentSpread: 1.6,
    restitution: 0.1,
    density: 0.002,
    hardnessFactor: 0.6,
    color: '#a8d8ea',
    crackedColor: '#6ba3be',
    outlineColor: '#3a7ca5',
    glowColor: 'rgba(168,216,234,0.35)',
    label: 'Brittle',
  },
  wood: {
    strength: 620,
    crackThreshold: 260,
    fragmentCount: 6,
    fragmentSpread: 0.85,
    restitution: 0.2,
    density: 0.004,
    hardnessFactor: 1.0,
    color: '#c4a265',
    crackedColor: '#8b6914',
    outlineColor: '#5a3e1b',
    glowColor: 'rgba(196,162,101,0.25)',
    label: 'Sturdy',
  },
  steel: {
    strength: 1400,
    crackThreshold: 800,
    fragmentCount: 0,
    fragmentSpread: 0.3,
    restitution: 0.55,
    density: 0.012,
    hardnessFactor: 1.6,
    color: '#8a9ba8',
    crackedColor: '#5a6b78',
    outlineColor: '#2c3e50',
    glowColor: 'rgba(138,155,168,0.2)',
    label: 'Armored',
  },
};

// Pre-computed fragment vertex sets (relative coords, normalized to [-0.5, 0.5])
// Each entry is an array of polygons (vertex arrays) that tile a unit rectangle.
const RECT_FRAGMENTS_10 = [
  [[-0.5,-0.5],[-0.1,-0.5],[-0.15,0.0],[-0.5,0.05]],
  [[-0.1,-0.5],[0.25,-0.5],[0.2,-0.1],[-0.05,-0.15]],
  [[0.25,-0.5],[0.5,-0.5],[0.5,-0.15],[0.28,-0.05]],
  [[-0.5,0.05],[-0.15,0.0],[-0.1,0.3],[-0.45,0.35]],
  [[-0.15,0.0],[0.2,-0.1],[0.15,0.25],[-0.1,0.3]],
  [[0.2,-0.1],[0.28,-0.05],[0.5,0.1],[0.5,0.4],[0.15,0.25]],
  [[-0.5,0.35],[-0.1,0.3],[-0.12,0.5],[-0.5,0.5]],
  [[-0.1,0.3],[0.15,0.25],[0.1,0.5],[-0.12,0.5]],
  [[0.15,0.25],[0.5,0.4],[0.5,0.5],[0.1,0.5]],
  [[0.28,-0.05],[0.5,-0.15],[0.5,0.1]],
];

const RECT_FRAGMENTS_6 = [
  [[-0.5,-0.5],[0.05,-0.5],[0.0,-0.17],[-0.5,-0.2]],
  [[0.05,-0.5],[0.5,-0.5],[0.5,-0.15],[0.0,-0.17]],
  [[-0.5,-0.2],[0.0,-0.17],[0.05,0.18],[-0.5,0.15]],
  [[0.0,-0.17],[0.5,-0.15],[0.5,0.2],[0.05,0.18]],
  [[-0.5,0.15],[0.05,0.18],[0.0,0.5],[-0.5,0.5]],
  [[0.05,0.18],[0.5,0.2],[0.5,0.5],[0.0,0.5]],
];

export function getFragmentVerts(count) {
  return count >= 10 ? RECT_FRAGMENTS_10 : RECT_FRAGMENTS_6;
}

export function evaluateImpact(speed, mass, material, impactMultiplier) {
  const impulse = speed * mass * impactMultiplier;
  if (impulse >= material.strength) return 'SHATTER';
  if (impulse >= material.crackThreshold) return 'CRACK';
  return 'SURVIVE';
}

export function generateCrackPattern(count = 5) {
  const lines = [];
  for (let i = 0; i < count; i++) {
    const angle = (Math.random() * Math.PI * 2);
    const len = 0.2 + Math.random() * 0.35;
    lines.push({ angle, len });
  }
  return lines;
}

