*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

body {
  background: #1a1a2e;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  font-family: 'Segoe UI', system-ui, sans-serif;
  overflow: hidden;
}

#game-container {
  position: relative;
  user-select: none;
}

#game-canvas {
  display: block;
  border-radius: 12px;
  box-shadow: 0 0 40px rgba(0,0,0,0.6);
  cursor: crosshair;
}

/* Yoyo picker */
#yoyo-picker {
  position: absolute;
  bottom: 20px;
  left: 50%;
  transform: translateX(-50%);

