  "open_questions": [
    "Fling mode decision: keep, repurpose, or cut? (UI hidden in index.html; logic intact in codebase)"
  ],
  "milestones": [
    { "name": "Push mode playable", "status": "completed" },
    { "name": "Fling mode decision made", "status": "pending" },
    { "name": "Push mode polished (balance + levels + feedback)", "status": "pending" },
    { "name": "Mobile / HiDPI support", "status": "pending" }
  ],
  "decisions": [
    {
      "date": "2026-05-20",
      "decision": "Push mode only for now — fling mode UI hidden, selectedMode hardcoded to 'push'",
      "rationale": "Ship a polished single mode rather than two half-finished modes"
    },
    {
      "date": "2026-05-20",
      "decision": "Vanilla JS + Matter.js, no build system, Canvas 2D",
      "rationale": "No build complexity for a game of this scope; Matter.js loaded via CDN"
    },
    {
      "date": "2026-05-20",
      "decision": "Test framework: Vitest (already set up)",
      "rationale": "Modern, fast, ESM-native — compatible with the project's ES6 module structure"
    },
    {
      "date": "2026-05-20",
      "decision": "Add hit combo multiplier to push mode: each hit within 1s raises damage by 0.5×, capped at 3.0×",
      "rationale": "Rewards skilled rapid swinging without changing the core one-hit-ideal scoring loop"
    },
    {
      "date": "2026-05-20",
      "decision": "Keep fling mode as a selectable second mode; push mode is the default and primary",
      "rationale": "Both mechanics are worth keeping — push for sustained swinging, fling for projectile precision"
    }
  ],
  "notes": "CLAUDE.md says no test framework yet — this is incorrect. Vitest is set up (vitest.config.js, tests/ dir, TEST_SPEC.md). Update CLAUDE.md."
}

